<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import request from '@/utils/request'; import type { ApiResponse, Course } from '@/types'
const courses=ref<Course[]>([]); const categories=ref<any[]>([]); const visible=ref(false); const form=reactive({title:'',description:'',category_id:undefined as number|undefined,difficulty:'beginner'}); async function load(){const [a,b]=await Promise.all([request.get<ApiResponse<Course[]>>('/teacher/courses'),request.get<ApiResponse<any[]>>('/course-categories')]);courses.value=a.data.data;categories.value=b.data.data} async function create(){await request.post('/courses',form);visible.value=false;ElMessage.success('课程草稿已创建');await load()} onMounted(load)
</script>
<template><section class="page"><header class="page-header"><div><p class="eyebrow">TEACHER STUDIO</p><h1>教师工作台</h1><p>从课程构思，到发布与数据复盘。</p></div><el-button type="primary" size="large" @click="visible=true">创建课程</el-button></header><div class="metric-grid"><article><span>课程总数</span><strong>{{ courses.length }}</strong><small>我的课程</small></article><article><span>已发布</span><strong>{{ courses.filter(c=>c.status==='published').length }}</strong><small>对学员可见</small></article><article><span>待审核</span><strong>{{ courses.filter(c=>c.status==='pending_review').length }}</strong><small>正在流转</small></article><article><span>学员总数</span><strong>{{ courses.reduce((n,c)=>n+c.student_count,0) }}</strong><small>累计加入</small></article></div><div class="panel table-panel"><el-table :data="courses"><el-table-column prop="title" label="课程"/><el-table-column prop="difficulty" label="难度"/><el-table-column prop="student_count" label="学员"/><el-table-column prop="status" label="状态"><template #default="scope"><el-tag>{{ scope.row.status }}</el-tag></template></el-table-column><el-table-column label="操作"><template #default="scope"><el-button link type="primary" @click="$router.push(`/app/teacher?course=${scope.row.id}`)">管理</el-button></template></el-table-column></el-table></div><el-dialog v-model="visible" title="创建课程" width="520"><el-form label-position="top"><el-form-item label="课程名称"><el-input v-model="form.title"/></el-form-item><el-form-item label="课程简介"><el-input v-model="form.description" type="textarea"/></el-form-item><el-form-item label="分类"><el-select v-model="form.category_id" style="width:100%"><el-option v-for="c in categories" :key="c.id" :label="c.name" :value="c.id"/></el-select></el-form-item><el-form-item label="难度"><el-radio-group v-model="form.difficulty"><el-radio-button value="beginner">入门</el-radio-button><el-radio-button value="intermediate">进阶</el-radio-button><el-radio-button value="advanced">高级</el-radio-button></el-radio-group></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="create">创建草稿</el-button></template></el-dialog></section></template>
